ADMIN_REMAINDER_LOCALES = {code for code, _ in LANGUAGE_OPTIONS if code != "en"}
if len(ADMIN_REMAINDER_KEYS) != 32 or len(set(ADMIN_REMAINDER_KEYS)) != 32:
    raise ValueError("Admin remainder source list must contain 32 unique keys")
if set(ADMIN_REMAINDER_ROWS) != ADMIN_REMAINDER_LOCALES:
    raise ValueError("Admin remainder catalog locale coverage is incomplete")
if any(
    len(row.split("|")) != len(ADMIN_REMAINDER_KEYS)
    for row in ADMIN_REMAINDER_ROWS.values()
):
    raise ValueError("Admin remainder row length is invalid")

ADMIN_REMAINDER_CATALOGS: dict[str, dict[str, str]] = {
    locale: dict(zip(ADMIN_REMAINDER_KEYS, row.split("|"), strict=True))
    for locale, row in ADMIN_REMAINDER_ROWS.items()
}
_formatter = string.Formatter()
for _locale, _entries in ADMIN_REMAINDER_CATALOGS.items():
    for _source, _value in _entries.items():
        _source_slots = Counter(
            name for _, name, _, _ in _formatter.parse(_source) if name
        )
        _value_slots = Counter(
            name for _, name, _, _ in _formatter.parse(_value) if name
        )
        if not _value.strip() or _source_slots != _value_slots:
            raise ValueError(
                f"Admin remainder catalog validation failed for {_locale}: {_source}"
            )
